//! The hard-sphere contact radial distribution function of the cubic
//! association model against the exact-source library.
//! Generated by tools/rust_port/validate_cpa_rdf.py.
//! Copyright thermotools and Contributors. Apache-2.0.

#![allow(clippy::excessive_precision)]

use thermopack_rs::rdf::cpa_rdf;

const ATOL: f64 = 1.0e-14;
const RTOL: f64 = 1.0e-12;

#[test]
fn the_radial_function_matches_the_source() {
    let mut rows = include_str!("fixtures/cpa_rdf.csv").lines();
    let header = rows.next().expect("the header of the fixture");
    assert_eq!(header, "case;g;g_t;g_v;g_n;g_tt;g_tv;g_tn;g_vv;g_vn;g_nn");
    let mut compared = 0;
    for row in rows {
        let fields: Vec<&str> = row.split(';').collect();
        assert_eq!(fields.len(), 11, "row {row}");
        let case: Vec<&str> = fields[0].split('|').collect();
        assert_eq!(case.len(), 4, "case {row}");
        let component = case[0];
        let temperature: f64 = case[1].parse().expect("the temperature");
        let volume: f64 = case[2].parse().expect("the volume");
        let moles: Vec<f64> = case[3]
            .split(',')
            .map(|value| value.parse().expect("the number of moles"))
            .collect();
        let model = thermopack_rs::Cpa::new(&[component]).expect("the model of the case");
        let rdf = cpa_rdf(&model, temperature, volume, &moles).expect("the radial function");
        let native = [
            rdf.g,
            rdf.temperature,
            rdf.volume,
            rdf.moles[0],
            rdf.temperature_second,
            rdf.temperature_volume,
            rdf.temperature_moles[0],
            rdf.volume_second,
            rdf.volume_moles[0],
            rdf.moles_second[0],
        ];
        for (position, (source, native)) in fields[1..].iter().zip(native.iter()).enumerate() {
            let source: f64 = source.parse().expect("the source value");
            assert!(
                (source - native).abs() <= ATOL + RTOL * source.abs(),
                "entry {position} of the case {row}: source {source} native {native}"
            );
        }
        compared += 1;
    }
    assert!(compared > 0, "the fixture holds no case");
}

#[test]
fn the_temperature_derivatives_vanish() {
    // The hard-sphere contact function of the cubic association model does not
    // depend on the temperature.
    let model = thermopack_rs::Cpa::new(&["H2O"]).expect("the model");
    let rdf = cpa_rdf(&model, 300.0, 1.0e-3, &[1.0]).expect("the radial function");
    assert_eq!(rdf.temperature, 0.0);
    assert_eq!(rdf.temperature_second, 0.0);
    assert_eq!(rdf.temperature_volume, 0.0);
    assert_eq!(rdf.temperature_moles[0], 0.0);
    assert!(rdf.g > 0.0);
}

#[test]
fn a_wrong_number_of_moles_is_rejected() {
    let model = thermopack_rs::Cpa::new(&["H2O"]).expect("the model");
    assert!(cpa_rdf(&model, 300.0, 1.0e-3, &[1.0, 1.0]).is_err());
    assert!(cpa_rdf(&model, 300.0, 1.0e-3, &[]).is_err());
    assert!(cpa_rdf(&model, 300.0, -1.0e-3, &[1.0]).is_err());
    assert!(cpa_rdf(&model, 300.0, 1.0e-3, &[0.0]).is_err());
}
